{"node_id": "NRS_484B_270_2b_o3", "law_refs": ["NRS-484B-270-2b"], "subject": {"binder": "subject", "class_elements": ["ru.aggregate=DEF-NRS-484A-130::motor_vehicle"]}, "segmentation": [{"id": "b1", "text": "When overtaking or passing", "role": "trigger"}, {"id": "b2", "text": "a bicycle, an electric bicycle or an electric scooter", "role": "trigger"}, {"id": "b3", "text": "proceeding in the same direction,", "role": "trigger"}, {"id": "b4", "text": "the driver of a motor vehicle", "role": "subject"}, {"id": "b5", "text": "shall exercise due care and:", "role": "sibling"}, {"id": "b6", "text": "If there is only one lane for traffic proceeding in the same direction,", "role": "condition"}, {"id": "b7", "text": "pass to the left of the bicycle, electric bicycle or electric scooter", "role": "sibling"}, {"id": "b8", "text": "at a safe distance, which must be not less than 3 feet between any portion of the vehicle and the bicycle, electric bicycle or electric scooter,", "role": "sibling"}, {"id": "b9", "text": "and shall not move again to the right side of the highway", "role": "obligation"}, {"id": "b10", "text": "until the vehicle is safely clear of the overtaken bicycle, electric bicycle or electric scooter.", "role": "standard"}, {"id": "b11", "text": "Except as otherwise provided in NRS 484B.213 and 484B.217 [NRS-484B-213-1, NRS-484B-213-2a, NRS-484B-213-2b, NRS-484B-213-2c, NRS-484B-217-2],", "role": "reference"}, {"id": "b12", "text": "when passing to the left of a bicycle, electric bicycle or electric scooter at a safe distance of not less than 3 feet between any portion of the vehicle and the bicycle, electric bicycle or electric scooter, this paragraph authorizes the driver, if it is safe, to pass: (1) To the left of the center of the highway. (2) In a no-passing zone.", "role": "exception"}], "elements": [{"span": "b1", "atoms": ["rel.longitudinal_overlap"], "derived": ["drv.interaction.overtake_pass"], "justification": "'overtaking or passing' a road user pr